head.script:
// jQuery 조회 순서(받은 선택자 → 없으면 mf_ 접두사). 2026-11
scwin.__getJq = function(q) {
    var j = $(q); if (j.length) return j;
    var P = 'mf_', t = q.trim(), r = t.slice(1);
    if (r.slice(0, 2) === 'G_') r = 'G_' + P + r.slice(2); else if (r.slice(0, P.length) !== P) r = P + r;
    return $(t.slice(0, 1) + r);
};
scwin.onpageload = function() {
    ui_wframe.setSrc("wframe_.scheduleCalendar_setSRc_WPF-1743_(WSQ-3190)_sub.xml");
};
scwin.onpageunload = function() {};
scwin.__isWidth = function() {
    var el = $('td').find(".fc-widget-content");
    for (var i = 0; i < el.length; i++) {
        var el1 = scwin.__getJq(el)[i];
        if (scwin.__getJq(el1).css("width") == "0px") {
            return false;
        }
    }
    return true;
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    //Function unitTest
    //Create buy Truong.Luu
    //Create date 20-Mar-2018
    //End unitTest
}
